import pickle
import base64
import sys
import json
import os
from io import BytesIO


class TaskProcessor:
    """Processes serialized task objects from the job queue.
    Tasks are Python objects serialized with pickle for flexibility.
    """

    def __init__(self, config_path=None):
        self.config_path = config_path or os.environ.get('TASK_CONFIG', '/etc/tasks/config.json')
        self.allowed_modules = ['tasks', 'models', 'handlers']
        self.max_payload_size = 1024 * 1024  # 1MB

    def validate_size(self, data):
        if len(data) > self.max_payload_size:
            raise ValueError(f"Payload exceeds maximum size of {self.max_payload_size} bytes")
        return True

    def check_header(self, raw_bytes):
        """Verify pickle protocol header is present"""
        if len(raw_bytes) < 2:
            raise ValueError("Invalid payload: too short")
        # Check for valid pickle opcodes at start
        if raw_bytes[0:1] not in [b'\x80', b'(', b']', b'}']:
            raise ValueError("Invalid payload: unrecognized format")
        return True

    def deserialize_task(self, payload_b64):
        """Deserialize a base64-encoded pickle payload into a task object."""
        try:
            raw_bytes = base64.b64decode(payload_b64)
            self.validate_size(raw_bytes)
            self.check_header(raw_bytes)

            # Deserialize the task object
            task = pickle.loads(raw_bytes)
            return task
        except Exception as e:
            return {"error": str(e)}

    def execute_task(self, task):
        """Execute the deserialized task object."""
        if hasattr(task, 'run'):
            return task.run()
        elif isinstance(task, dict):
            return {"status": "processed", "result": task}
        else:
            return {"status": "unknown_task_type", "type": str(type(task))}


def handler(event, context):
    """AWS Lambda handler for processing task submissions."""
    try:
        if event.get('requestContext', {}).get('http', {}).get('method') == 'OPTIONS':
            return {
                'statusCode': 200,
                'headers': {'Access-Control-Allow-Origin': '*'},
                'body': ''
            }

        body = event.get('body', '')
        if event.get('isBase64Encoded', False):
            body = base64.b64decode(body).decode('utf-8')

        request_data = json.loads(body) if isinstance(body, str) else body

        task_payload = request_data.get('task_payload')
        if not task_payload:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing task_payload field'})
            }

        processor = TaskProcessor()
        task = processor.deserialize_task(task_payload)

        if isinstance(task, dict) and 'error' in task:
            return {
                'statusCode': 422,
                'body': json.dumps(task)
            }

        result = processor.execute_task(task)

        return {
            'statusCode': 200,
            'headers': {'Content-Type': 'application/json'},
            'body': json.dumps({'status': 'success', 'result': str(result)})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Internal error: {str(e)}'})
        }


if __name__ == '__main__':
    # CLI mode for local testing
    if len(sys.argv) > 1:
        payload = sys.argv[1]
    else:
        payload = sys.stdin.read().strip()

    processor = TaskProcessor()
    task = processor.deserialize_task(payload)
    result = processor.execute_task(task)
    print(json.dumps(result, default=str))
